const input = $input.first().json;
const headers = input.headers || {};
const apiKey = headers['x-api-key'] || headers['authorization']?.replace('Bearer ', '');

if (!apiKey) return [{ json: { error: true, status: 401, message: 'API key required' } }];

const body = input.body || input;
const contact = {
  email: body.email,
  first_name: body.first_name || body.firstName || '',
  last_name: body.last_name || body.lastName || '',
  company: body.company || body.organization || '',
  phone: body.phone || body.phoneNumber || '',
  source: body.source || 'api',
  tags: body.tags || [],
  custom_fields: body.custom_fields || body.properties || {}
};

if (!contact.email) return [{ json: { error: true, status: 400, message: 'Email required' } }];

return [{ json: { ...contact, api_key: apiKey } }];

const input = $input.first().json;
const body = input.body || input;

return [{ json: {
  email: body.email,
  event_name: body.event || body.event_name,
  properties: body.properties || body.data || {},
  timestamp: body.timestamp || new Date().toISOString(),
  api_key: (input.headers || {})['x-api-key']
}}];
